draw((0,-2.2)--(0,2.2));

for (i = -1; i <= 4; ++i) {
  dot(2*dir(30*i),red + linewidth(4*bp));
}

for (i = 5; i <= 10; ++i) {
  dot(2*dir(30*i),blue + linewidth(4*bp));
}
[/asy]

